static void rtl_splay_replace(RTL_SPLAY_LINKS *x, RTL_SPLAY_LINKS *y, RTL_SPLAY_LINKS **root)
{
    if (RtlIsRoot(x))
        *root = y;
    else if (RtlIsLeftChild(x))
        x->Parent->LeftChild = y;
    else
        x->Parent->RightChild = y;

    if (y)
        y->Parent = RtlIsRoot(x) ? y : x->Parent;
}
